/**
 * Public surface of the ChatGPT direct provider.
 *
 * Transport: Playwright (persistent Chrome profile) — see ./transport.ts.
 *
 * Two entry points:
 *   - `chat()`        — high-level: one prompt → text, auto-continues on
 *                       truncation across multiple turns. Threads the
 *                       conversation_id + parent_message_id for you.
 *   - `completion()`  — low-level: single SSE round-trip. Caller manages
 *                       conversation_id / parentMessageId.
 *
 * Lifecycle:
 *   - First call lazily launches headless Chrome (~2s) using a persistent
 *     profile at `<cwd>/.chatgpt-research/chrome-profile`.
 *   - `createSession()` once per logical conversation; reuse `sessionId`
 *     across `chat()` calls.
 *   - On graceful shutdown, call `close()` to release the browser.
 *
 * First-time setup:
 *   npm run chatgpt:setup     — opens a visible window, sign in once, profile saved.
 */
export {
  // Core
  createSession,
  completion,
  chat,
  // Transport lifecycle
  close,
  getSession,
  requireSession,
  // SSE parser (testable / advanced)
  createSseParser,
  // Errors
  ChatGPTError,
  ChatGPTAuthError,
  ChatGPTRateLimitError,
  ChatGPTAbortedError,
  ChatGPTProtocolError,
  ChatGPTTransportError,
} from "./direct.js";

export type {
  SessionHandle,
  CompletionOpts,
  CompletionResult,
  ChatOpts,
  ChatResult,
  SseParserCallbacks,
  SseParserState,
} from "./direct.js";

export type { SessionInfo } from "./transport.js";
